<section class="panel keyword-manager" aria-labelledby="keywords-title"><div class="section-head"><h2 id="keywords-title">Palavras-chave</h2></div><?php if ($canManageKeywords): ?><form method="post" action="<?= site_url('pecas/'.$piece['id'].'/palavras-chave') ?>" class="stack"><?= csrf_field() ?><fieldset><legend>Palavras-chave disponíveis</legend><?php if ($terms): ?><div class="piece-term-options"><?php $currentCategory = null; ?><?php foreach ($terms as $term): ?><?php if ($currentCategory !== $term['vocabulary_id']): ?><?php if ($currentCategory !== null): ?></div></div><?php endif ?><?php $currentCategory = $term['vocabulary_id']; ?><div class="piece-term-group"><strong><?= esc($term['vocabulary_name']) ?></strong><div><?php endif ?><label><input type="checkbox" name="term_ids[]" value="<?= esc($term['id']) ?>" <?= in_array($term['id'], $selectedTermIds, true) ? 'checked' : '' ?>> <?= esc($term['label']) ?></label><?php endforeach ?></div></div></div><?php else: ?><p class="muted">Nenhuma palavra-chave cadastrada.</p><?php endif ?></fieldset><?php if ($canManageCategories): ?><div class="new-keyword-fields"><label>Categoria<select name="vocabulary_id"><option value="">Selecione uma categoria</option><?php foreach ($vocabularies as $vocabulary): ?><option value="<?= esc($vocabulary['id']) ?>"><?= esc($vocabulary['name']) ?></option><?php endforeach ?></select></label><label>Nova categoria<input type="text" name="new_category" maxlength="190" placeholder="Cria e seleciona uma categoria"></label><label>Nova palavra-chave<input type="text" name="new_keyword" maxlength="190"></label></div><?php endif ?><p class="form-help">Desmarque uma palavra-chave para removê-la desta peça. O termo continuará disponível no sistema.</p><button class="button" type="submit">Salvar palavras-chave</button></form><?php else: ?><div class="piece-keywords"><?php foreach ($terms as $term): ?><?php if (in_array($term['id'], $selectedTermIds, true)): ?><span><?= esc($term['label']) ?></span><?php endif ?><?php endforeach ?><?php if (! $selectedTermIds): ?><span class="no-keywords">Sem palavras-chave</span><?php endif ?></div><?php endif ?></section>
<section class="panel"><div class="section-head"><h2>Ativos</h2></div><?php foreach ($assets as $asset): ?><article class="asset-row"><div><strong><?= esc($asset['name']) ?></strong><span><?= esc($asset['type']) ?> · <?= esc($asset['version_count']) ?> versão(ões)</span></div><a href="<?= site_url('ativos/'.$asset['id'].'/versoes/nova') ?>">Nova versão</a></article><?php endforeach ?><?php if (!$assets): ?><div class="empty"><p>Esta peça ainda não possui ativos.</p><a href="<?= site_url('pecas/'.$piece['id'].'/ativos/novo') ?>">Adicionar o primeiro ativo</a></div><?php endif ?></section></div>
<aside class="panel piece-preview" aria-labelledby="preview-title"><div class="section-head"><h2 id="preview-title">Pré-visualização</h2></div><?php if ($previewFile && $previewType === 'image'): ?><img src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" alt="Pré-visualização de <?= esc($piece['title']) ?>"><?php elseif ($previewFile && $previewType === 'video'): ?><video controls preload="metadata"><source src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" type="<?= esc($previewFile['mime_type']) ?>">Seu navegador não consegue reproduzir este vídeo.</video><?php elseif ($previewFile && $previewType === 'audio'): ?><div class="audio-preview"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt=""><audio controls preload="metadata"><source src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" type="<?= esc($previewFile['mime_type']) ?>">Seu navegador não consegue reproduzir este áudio.</audio></div><?php elseif ($previewFile && $previewType === 'pdf'): ?><iframe src="<?= site_url('pecas/'.$piece['id'].'/preview') ?>" title="Pré-visualização de <?= esc($piece['title']) ?>"></iframe><?php elseif ($previewFile): ?><div class="preview-unavailable"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt=""><p>Pré-visualização indisponível para este formato.</p></div><?php else: ?><div class="preview-unavailable"><img src="<?= site_url('pecas/'.$piece['id'].'/miniatura') ?>" alt=""><p>Nenhum arquivo disponível para pré-visualização.</p></div><?php endif ?><?php if ($previewFile): ?><p class="preview-file-name"><?= esc($previewFile['original_name']) ?></p><?php endif ?></aside></div>
